impl<'input,I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>> Actions<'input, BaseParserType<'input,I>> for PythonParserExt<'input>{
	fn get_grammar_file_name(&self) -> & str{ "PythonParser.g4"}

   	fn get_rule_names(&self) -> &[& str] {&ruleNames}

   	fn get_vocabulary(&self) -> &dyn Vocabulary { &**VOCABULARY }
	fn sempred(_localctx: Option<&(dyn PythonParserContext<'input> + 'input)>, rule_index: isize, pred_index: isize,
			   recog:&mut BaseParserType<'input,I>
	)->bool{
		match rule_index {
					28 => PythonParser::<'input,I,_>::dotted_name_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					128 => PythonParser::<'input,I,_>::bitwise_or_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					129 => PythonParser::<'input,I,_>::bitwise_xor_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					130 => PythonParser::<'input,I,_>::bitwise_and_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					131 => PythonParser::<'input,I,_>::shift_expr_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					132 => PythonParser::<'input,I,_>::sum_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					133 => PythonParser::<'input,I,_>::term_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					137 => PythonParser::<'input,I,_>::primary_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					188 => PythonParser::<'input,I,_>::t_primary_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
			_ => true
		}
	}
}

