impl<'input, I, H> PythonParser<'input, I, H>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
    H: ErrorStrategy<'input,BaseParserType<'input,I>>
{
	pub fn file_input(&mut self,)
	-> Result<Rc<File_inputContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = File_inputContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 0, RULE_file_input);
        let mut _localctx: Rc<File_inputContextAll> = _localctx;
		let mut _la: isize = -1;
		let result: Result<(), ANTLRError> = (|| {

			//recog.base.enter_outer_alt(_localctx.clone(), 1);
			recog.base.enter_outer_alt(None, 1);
			{
			recog.base.set_state(393);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			if ((((_la - 5)) & !0x3f) == 0 && ((1usize << (_la - 5)) & ((1usize << (FSTRING_START - 5)) | (1usize << (LPAR - 5)) | (1usize << (LSQB - 5)) | (1usize << (LBRACE - 5)) | (1usize << (PLUS - 5)) | (1usize << (MINUS - 5)) | (1usize << (STAR - 5)) | (1usize << (TILDE - 5)))) != 0) || ((((_la - 50)) & !0x3f) == 0 && ((1usize << (_la - 50)) & ((1usize << (AT - 50)) | (1usize << (ELLIPSIS - 50)) | (1usize << (FALSE - 50)) | (1usize << (AWAIT - 50)) | (1usize << (IMPORT - 50)) | (1usize << (PASS - 50)) | (1usize << (NONE - 50)) | (1usize << (BREAK - 50)) | (1usize << (RAISE - 50)) | (1usize << (TRUE - 50)) | (1usize << (CLASS - 50)) | (1usize << (RETURN - 50)) | (1usize << (CONTINUE - 50)) | (1usize << (FOR - 50)) | (1usize << (LAMBDA - 50)) | (1usize << (TRY - 50)) | (1usize << (DEF - 50)) | (1usize << (FROM - 50)) | (1usize << (NONLOCAL - 50)) | (1usize << (WHILE - 50)) | (1usize << (ASSERT - 50)))) != 0) || ((((_la - 82)) & !0x3f) == 0 && ((1usize << (_la - 82)) & ((1usize << (DEL - 82)) | (1usize << (GLOBAL - 82)) | (1usize << (NOT - 82)) | (1usize << (WITH - 82)) | (1usize << (ASYNC - 82)) | (1usize << (IF - 82)) | (1usize << (YIELD - 82)) | (1usize << (NAME_OR_TYPE - 82)) | (1usize << (NAME_OR_MATCH - 82)) | (1usize << (NAME_OR_CASE - 82)) | (1usize << (NAME_OR_WILDCARD - 82)) | (1usize << (NAME - 82)) | (1usize << (NUMBER - 82)) | (1usize << (STRING - 82)))) != 0) {
				{
				/*InvokeRule statements*/
				recog.base.set_state(392);
				recog.statements()?;

				}
			}

			recog.base.set_state(395);
			recog.base.match_token(EOF,&mut recog.err_handler)?;

			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule();

		Ok(_localctx)
	}
}
